using System.Collections.Generic;
using UnityEngine;
using Verse;

namespace KRWF.RimKata
{
    // Each ring stores its inclusive north-to-northeast wedge.
    internal sealed class RimKataRingTraversal
    {
        private const int MaximumPrecomputedRing = 256;
        private static readonly Dictionary<int, IntVec3[]> FallbackWedges =
            new Dictionary<int, IntVec3[]>();
        private IntVec3[] fallback;
        private int wedgeStart;
        private int wedgeCount;
        private int direction;
        private bool clockwise;
        private int octantStep;
        private int wedgeIndex;
        private int emitted;
        private bool centerPending;
        private float outerSquared;
        private bool clippedOuter;

        internal int CellCount { get; private set; }
        internal bool Complete => emitted >= CellCount;

        internal void Clear()
        {
            fallback = null;
            wedgeStart = 0;
            wedgeCount = 0;
            octantStep = 8;
            emitted = 0;
            centerPending = false;
            CellCount = 0;
        }

        internal void Reset(int ring, float outerRadius, int heading, bool turnClockwise)
        {
            Clear();
            if (ring <= 0)
            {
                return;
            }
            direction = heading & 7;
            clockwise = turnClockwise;
            outerSquared = outerRadius * outerRadius;
            clippedOuter = outerRadius != ring + RimKataRangeUtility.CandidateCellRadiusPadding;
            if (ring <= MaximumPrecomputedRing)
            {
                wedgeStart = WedgeStarts[ring];
                wedgeCount = WedgeStarts[ring + 1] - wedgeStart;
            }
            else
            {
                if (!FallbackWedges.TryGetValue(ring, out fallback))
                {
                    fallback = BuildFallbackWedge(ring);
                    FallbackWedges.Add(ring, fallback);
                }
                wedgeCount = fallback.Length;
            }

            centerPending = ring == 1;
            CellCount = centerPending ? 1 : 0;
            if (!clippedOuter)
            {
                CellCount += wedgeCount * 8;
                if (wedgeCount > 0)
                {
                    if (WedgeOffset(0).x == 0)
                    {
                        CellCount -= 4;
                    }
                    IntVec3 last = WedgeOffset(wedgeCount - 1);
                    if (last.x == last.z)
                    {
                        CellCount -= 4;
                    }
                }
            }
            else
            {
                for (int i = 0; i < wedgeCount; i++)
                {
                    IntVec3 offset = WedgeOffset(i);
                    if ((float)((long)offset.x * offset.x + (long)offset.z * offset.z)
                        <= outerSquared)
                    {
                        CellCount += offset.x == 0 || offset.x == offset.z ? 4 : 8;
                    }
                }
            }
            octantStep = 0;
            ResetWedgeIndex();
        }

        internal bool TryNext(out IntVec3 offset)
        {
            offset = IntVec3.Invalid;
            if (Complete)
            {
                return false;
            }
            if (centerPending)
            {
                centerPending = false;
                emitted++;
                offset = IntVec3.Zero;
                return true;
            }

            while (octantStep < 8)
            {
                if (wedgeIndex < 0 || wedgeIndex >= wedgeCount)
                {
                    octantStep++;
                    if (octantStep < 8)
                    {
                        ResetWedgeIndex();
                    }
                    continue;
                }

                int octant = CurrentOctant();
                bool forward = ((octant & 1) == 0) == clockwise;
                IntVec3 wedge = WedgeOffset(wedgeIndex);
                wedgeIndex += forward ? 1 : -1;
                // Include the starting ray, exclude the ending ray in every octant.
                if ((forward ? wedge.x == wedge.z : wedge.x == 0)
                    || (clippedOuter
                        && (float)((long)wedge.x * wedge.x + (long)wedge.z * wedge.z)
                            > outerSquared))
                {
                    continue;
                }

                int x = (octant & 1) == 0 ? wedge.x : wedge.z;
                int z = (octant & 1) == 0 ? wedge.z : wedge.x;
                switch (octant >> 1)
                {
                    case 0: offset = new IntVec3(x, 0, z); break;
                    case 1: offset = new IntVec3(z, 0, -x); break;
                    case 2: offset = new IntVec3(-x, 0, -z); break;
                    default: offset = new IntVec3(-z, 0, x); break;
                }
                emitted++;
                return true;
            }
            return false;
        }

        private int CurrentOctant()
        {
            return (direction + (clockwise ? octantStep : -octantStep - 1) + 16) & 7;
        }

        private void ResetWedgeIndex()
        {
            bool forward = ((CurrentOctant() & 1) == 0) == clockwise;
            wedgeIndex = forward ? 0 : wedgeCount - 1;
        }

        private IntVec3 WedgeOffset(int index)
        {
            if (fallback != null)
            {
                return fallback[index];
            }
            uint packed = PackedWedgeOffsets[wedgeStart + index];
            return new IntVec3((int)(packed >> 16), 0, (int)(packed & 65535u));
        }

        private static IntVec3[] BuildFallbackWedge(int ring)
        {
            float outer = ring + RimKataRangeUtility.CandidateCellRadiusPadding;
            float inner = ring - 1 + RimKataRangeUtility.CandidateCellRadiusPadding;
            float outerSq = outer * outer;
            float innerSq = inner * inner;
            int outerX = Mathf.FloorToInt(outer);
            int innerX = Mathf.FloorToInt(inner);
            List<IntVec3> offsets = new List<IntVec3>();
            for (int z = 0; z <= Mathf.FloorToInt(outer); z++)
            {
                long zSq = (long)z * z;
                while (outerX >= 0 && (float)((long)outerX * outerX + zSq) > outerSq)
                {
                    outerX--;
                }
                while (innerX >= 0 && (float)((long)innerX * innerX + zSq) > innerSq)
                {
                    innerX--;
                }
                for (int x = Mathf.Max(0, innerX + 1); x <= Mathf.Min(z, outerX); x++)
                {
                    offsets.Add(new IntVec3(x, 0, z));
                }
            }
            offsets.Sort(CompareWedgeOffsets);
            return offsets.ToArray();
        }

        private static int CompareWedgeOffsets(IntVec3 a, IntVec3 b)
        {
            long cross = (long)a.x * b.z - (long)b.x * a.z;
            if (cross != 0)
            {
                return cross < 0 ? -1 : 1;
            }
            long aSquared = (long)a.x * a.x + (long)a.z * a.z;
            long bSquared = (long)b.x * b.x + (long)b.z * b.z;
            return aSquared.CompareTo(bSquared);
        }

